#!/usr/bin/env python3
"""Generate 3 synthetic Excel files and expected.json."""
import json
from datetime import date
from pathlib import Path

from openpyxl import Workbook


def write(path, headers, rows):
    wb = Workbook()
    ws = wb.active
    ws.append(headers)
    for r in rows:
        ws.append(r)
    wb.save(path)


